WITH recent_subscriptions AS (SELECT *, FLOOR(monthly_fee) AS monthly_fee_whole FROM subscriptions WHERE status NOT IN ('PAUSED', 'CANCELLED', 'EXPIRED')), end_quarter_summary AS (SELECT QUARTER(end_date) AS end_quarter, DATE_FORMAT(start_date, 'yyyy-MM') AS start_month, SUM(CASE WHEN plan = 'premium' THEN 1 ELSE 0 END) AS premium_count FROM recent_subscriptions GROUP BY QUARTER(end_date), DATE_FORMAT(start_date, 'yyyy-MM')) SELECT end_quarter, start_month, premium_count FROM end_quarter_summary WHERE premium_count > 35 ORDER BY 1 DESC, start_month LIMIT 3;
